// Normaliza o envelope da UAZAPI para o contrato canônico do backend.
// Nenhuma regra de autorização/idempotência/domínio vive aqui.
const raw = $input.first().json;
const text = raw.text ?? raw.message ?? raw.body ?? '';
const phone = String(raw.phone ?? raw.from ?? raw.sender ?? '').replace(/\s/g, '');
const messageId = String(raw.messageId ?? raw.id ?? raw.message_id ?? 'msg-' + Date.now());
return [{
  json: {
    messageId,
    phone,
    text,
    timestamp: new Date().toISOString(),
    instance: raw.instance ?? 'camara-principal',
    metadata: raw.metadata ?? {}
  }
}];

// HMAC-SHA256 sobre `<timestamp>.<body>` usando o segredo compartilhado.
// Variáveis necessárias: FISCALIZA_API_URL, FISCALIZA_N8N_SECRET.
const crypto = require('crypto');
const item = $input.first().json;
const timestamp = new Date().toISOString();
const body = JSON.stringify(item);
const signature = crypto
  .createHmac('sha256', $env.FISCALIZA_N8N_SECRET)
  .update(timestamp + '.' + body)
  .digest('hex');
return [{ json: { timestamp, signature, body, item } }];
